import{_ as t,C as n,o as s,c as i,E as l,a2 as r}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"Weekly 003 — 所有权是智能体工作的控制平面","description":"","frontmatter":{"title":"Weekly 003 — 所有权是智能体工作的控制平面","date":"2026-08-02","column":"digital-employee","category":"weekly","summary":"对三篇经过证据验证的 Daily Research Notes 进行交叉分析后得出：可靠的智能体系统必须在每一个执行边界明确工作、控制、状态、权限、证据与完成的所有权。","sources":["Digital Employee Daily 003 — 计算机操作需要可观测的动作—状态循环","Industry Architecture Daily 003 — A2A 与 MCP 定义不同的互操作边界","Open-source Engineering Daily 003 — Manager 编排与 Handoff 表达不同的所有权模型"],"outline":"deep","cover":"/assets/covers/weekly-003-cover-v2.jpg"},"headers":[],"relativePath":"zh/research/weekly/weekly-003.md","filePath":"zh/research/weekly/weekly-003.md","lastUpdated":1787407830000}'),o={name:"zh/research/weekly/weekly-003.md"};function p(d,a,h,c,u,k){const e=n("ArticleCover");return s(),i("div",null,[l(e,{image:"/assets/covers/weekly-003-cover-v2.jpg",kicker:"研究周报 · 003",title:"所有权是智能体工作的控制平面",summary:"可靠的 Agent 系统不只是传递动作，而是在每个边界明确所有权、权限、证据与完成判断。",version:"W003",status:"发布于 2026-08-02",languageHref:"/en/research/weekly/weekly-003",languageLabel:"English"}),a[0]||(a[0]=r(`<h2 id="证据范围" tabindex="-1">证据范围 <a class="header-anchor" href="#证据范围" aria-label="Permalink to &quot;证据范围&quot;">​</a></h2><p>本期综合只使用 <strong>2026-07-27 至 2026-08-02</strong> 七天窗口内、已经通过证据验证的 Daily Research Notes。</p><p>共有三篇 Daily 笔记满足条件。三篇笔记均由 Research OS Engine Production Test V1 生产和验证，完整通过 Research Skills 流程，合并到 <code>main</code>，并从权威分支重新读取确认。</p><table tabindex="0"><thead><tr><th>栏目</th><th>合格 Daily 笔记</th><th>本期使用的已验证判断</th></tr></thead><tbody><tr><td>数字员工</td><td>计算机操作需要可观测的动作—状态循环</td><td>模型提出动作，外部 Runtime 执行、观察、治理并验证结果状态。</td></tr><tr><td>行业架构</td><td>A2A 与 MCP 定义不同的互操作边界</td><td>协议选择应依据工作、状态、政策与完成权归属，而不是只比较功能数量。</td></tr><tr><td>开源工程观察</td><td>Manager 编排与 Handoff 表达不同的所有权模型</td><td>专家调用和 Handoff 是不同操作，因为控制权与责任并不会以相同方式移动。</td></tr></tbody></table><p>Academic Observation、较早的 Weekly 报告和未验证资料均未进入证据集。因此，本报告综合的是一个规模较小但内部一致、经过生产验证的 Daily 集合，而不是把它包装成广泛市场调查。</p><h2 id="核心综合" tabindex="-1">核心综合 <a class="header-anchor" href="#核心综合" aria-label="Permalink to &quot;核心综合&quot;">​</a></h2><p>三篇 Daily 笔记研究的是三个不同表面：</p><ul><li>GUI 执行；</li><li>协议互操作；</li><li>多 Agent 编排。</li></ul><p>它们面对的底层架构问题却完全相同：</p><blockquote><p><strong>当系统只传递消息或动作，却没有保存谁拥有工作、谁控制执行、谁拥有状态、谁授予权限、谁可以声明完成、谁独立验证结果时，智能体工作就会失去治理基础。</strong></p></blockquote><p>本期形成的新结论是：<strong>所有权是智能体工作的控制平面。</strong></p><p>可靠的数字员工平台不能把计算机动作、MCP 调用、Manager 到专家的调用、Handoff 和 A2A 委派统一压扁成“工具调用”。它们是不同的工作边界，对应不同的所有权变化。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Position + WorkOrder</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>工作边界控制平面</span></span>
<span class="line"><span>  ├─ Computer Operation 边界</span></span>
<span class="line"><span>  ├─ Capability 边界（MCP）</span></span>
<span class="line"><span>  ├─ 内部委派边界</span></span>
<span class="line"><span>  ├─ Handoff 边界</span></span>
<span class="line"><span>  └─ 外部 Agent 边界（A2A）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Evidence Envelope</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>独立 Completion Verifier</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>接受结果，或进入受治理恢复</span></span></code></pre></div><p><em>图：joinwell52 Research Center 基于三篇合格 Daily Research Notes 的综合。</em></p><h2 id="本周关键发现" tabindex="-1">本周关键发现 <a class="header-anchor" href="#本周关键发现" aria-label="Permalink to &quot;本周关键发现&quot;">​</a></h2><ol><li><strong>执行与完成是两个不同事实。</strong> 点击成功、工具返回、专家回复或远程任务状态，都不自动等于业务结果完成。</li><li><strong>控制转移与工作贡献不是同一件事。</strong> Manager 可以继续承担最终责任而让专家贡献；Handoff 可以改变当前 Owner；外部 Agent 可以拥有委派任务，但调用方仍拥有验收权。</li><li><strong>协议功能趋同不会消除语义边界。</strong> MCP 与 A2A 都可以支持长任务，但仍然围绕不同的所有权关系组织。</li><li><strong>自治必须拆开定义。</strong> 操作自治可以提高，但权限自治仍应受 Position Policy 与人类审批约束。</li><li><strong>证据必须穿过每一个边界。</strong> 接收方不能只继承“已经成功”的叙述，而应收到足够支持独立验证的结构化 Evidence Envelope。</li></ol><h2 id="交叉分析" tabindex="-1">交叉分析 <a class="header-anchor" href="#交叉分析" aria-label="Permalink to &quot;交叉分析&quot;">​</a></h2><h3 id="_1-computer-use-暴露动作—状态缺口" tabindex="-1">1. Computer Use 暴露动作—状态缺口 <a class="header-anchor" href="#_1-computer-use-暴露动作—状态缺口" aria-label="Permalink to &quot;1. Computer Use 暴露动作—状态缺口&quot;">​</a></h3><p>计算机操作 Daily 将以下五个事实拆开：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>提出动作</span></span>
<span class="line"><span>→ 获得授权的动作</span></span>
<span class="line"><span>→ 实际执行的动作</span></span>
<span class="line"><span>→ 应用结果状态</span></span>
<span class="line"><span>→ 完成判断</span></span></code></pre></div><p>这说明 Agent 不能同时成为自己 GUI 工作的唯一执行者和最终裁判。模型可以提出动作；Harness 可以执行；目标应用拥有实际业务状态；任务专用 Validator 决定目标结果是否真正成立。</p><p>隐藏的所有权问题并不是“谁点击了按钮”，而是：</p><ul><li>谁拥有 WorkOrder；</li><li>谁被允许执行动作；</li><li>谁保存前状态与后状态；</li><li>谁负责重试或补偿；</li><li>谁有权关闭工作。</li></ul><h3 id="_2-mcp-与-a2a-暴露服务边界缺口" tabindex="-1">2. MCP 与 A2A 暴露服务边界缺口 <a class="header-anchor" href="#_2-mcp-与-a2a-暴露服务边界缺口" aria-label="Permalink to &quot;2. MCP 与 A2A 暴露服务边界缺口&quot;">​</a></h3><p>协议 Daily 表明，功能列表不是可靠的架构选择依据。MCP 和 A2A 都可以具有能力、长任务、进度、取消与异步行为。</p><p>真正稳定的区别是责任关系：</p><ul><li>MCP 通常是在 Host 控制的工作流内暴露能力；</li><li>A2A 通常是把有意义的一段工作委派给独立运行的 Agent 服务。</li></ul><p>因此，Protocol Adapter 不应暗中决定工作模型。WorkOrder 与 Position Contract 应先决定这是能力调用还是责任委派，再选择传输协议。</p><h3 id="_3-manager-与-handoff-暴露责任转移缺口" tabindex="-1">3. Manager 与 Handoff 暴露责任转移缺口 <a class="header-anchor" href="#_3-manager-与-handoff-暴露责任转移缺口" aria-label="Permalink to &quot;3. Manager 与 Handoff 暴露责任转移缺口&quot;">​</a></h3><p>编排 Daily 表明，Manager 调用专家时保留会话与完成所有权；Handoff 则改变当前 Agent，并可能转移后续责任。</p><p>因此，仅有 <code>from</code>、<code>to</code> 和自然语言消息不足以形成 Runtime 事实。系统必须记录操作类型：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>consult</span></span>
<span class="line"><span>assign_subtask</span></span>
<span class="line"><span>handoff</span></span>
<span class="line"><span>escalate</span></span>
<span class="line"><span>return</span></span></code></pre></div><p>没有类型，Runtime 就无法可靠重建谁负责集成、谁应用最终 Guardrail、谁可以声明完成。</p><h3 id="_4-统一边界矩阵" tabindex="-1">4. 统一边界矩阵 <a class="header-anchor" href="#_4-统一边界矩阵" aria-label="Permalink to &quot;4. 统一边界矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>边界</th><th>边界后的工作 Owner</th><th>控制 Owner</th><th>状态 Owner</th><th>完成声明者</th><th>验收验证者</th></tr></thead><tbody><tr><td>Computer Operation</td><td>通常仍由本地 WorkOrder Owner 承担责任</td><td>Execution Harness</td><td>目标应用与 Runtime Evidence Store</td><td>本地 Runtime 或 Worker</td><td>任务 Validator / 人类 Gate</td></tr><tr><td>MCP Capability Call</td><td>Host 通常保留工作所有权</td><td>Host 编排 Server Capability</td><td>Server Capability State 与 Host Workflow State</td><td>Host Workflow</td><td>Host 侧 Business Validator</td></tr><tr><td>Manager → Specialist</td><td>Manager 保留父工作所有权</td><td>Manager</td><td>Manager Run 与 Specialist Subtask State</td><td>Specialist 声明子任务结果；Manager 声明父任务完成</td><td>Manager、QA 或 Release Gate</td></tr><tr><td>Handoff</td><td>接收 Agent 成为转移范围的当前 Owner</td><td>接收 Agent，在 Runtime Policy 内运行</td><td>共享 Run State 与受治理 Context Transfer</td><td>接收 Agent 对转移范围声明完成</td><td>明确的下游 Gate 或返回后的 Owner</td></tr><tr><td>A2A Delegated Task</td><td>远程 Agent 拥有委派任务执行</td><td>远程 Agent Service</td><td>远程 Task Lifecycle；调用方保留本地 WorkOrder State</td><td>远程 Agent 报告 Task State 与 Artifact</td><td>调用方 Acceptance Validator</td></tr></tbody></table><p><em>表：joinwell52 Research Center 综合。</em></p><p>矩阵揭示了一个反复出现的规则：<strong>报告进度的一方，不一定是有权接受最终完成的一方。</strong></p><h2 id="新架构判断-工作边界控制平面" tabindex="-1">新架构判断：工作边界控制平面 <a class="header-anchor" href="#新架构判断-工作边界控制平面" aria-label="Permalink to &quot;新架构判断：工作边界控制平面&quot;">​</a></h2><p>Research Center 应在 Position 级工作与每一种执行 Adapter 之间建立 <strong>Work Boundary Control Plane（工作边界控制平面）</strong>。</p><p>它不是第二个 Workflow Engine，而是一个跨异构操作保存所有权语义与证据的层。</p><h3 id="必要对象" tabindex="-1">必要对象 <a class="header-anchor" href="#必要对象" aria-label="Permalink to &quot;必要对象&quot;">​</a></h3><ol><li><strong>WorkBoundaryContract</strong> —— 定义边界类型和允许的所有权变化。</li><li><strong>OwnershipLedger</strong> —— 持久记录边界前后的所有权事实。</li><li><strong>AuthorityDecision</strong> —— 记录政策判断与必要的人类批准。</li><li><strong>ContextPackage</strong> —— 只转移接收方完成工作所必需的上下文。</li><li><strong>EvidenceEnvelope</strong> —— 返回结构化观察、Artifact、状态引用与执行事实。</li><li><strong>CompletionVerifier</strong> —— 独立判断 WorkOrder 结果是否可以接受。</li></ol><h3 id="建议-contract" tabindex="-1">建议 Contract <a class="header-anchor" href="#建议-contract" aria-label="Permalink to &quot;建议 Contract&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">work_boundary_contract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  boundary_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_order_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  boundary_type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">capability_call | subtask | handoff | external_delegation | computer_operation</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  from_actor_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  to_actor_or_adapter_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_scope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_owner_before</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_owner_after</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  control_owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  state_owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  authority_source_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  context_package_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  expected_output_contract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evidence_envelope_contract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  completion_claimant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  completion_verifier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  retry_owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  compensation_owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  return_or_escalation_condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><h3 id="边界不变量" tabindex="-1">边界不变量 <a class="header-anchor" href="#边界不变量" aria-label="Permalink to &quot;边界不变量&quot;">​</a></h3><ul><li>任何边界都不得隐式改变工作所有权。</li><li>Completion Claim 不得自动成为 Accepted Outcome。</li><li>Context Transfer 必须遵循最小权限，并排除陈旧或不可信内容。</li><li>在执行后果性动作前，必须明确 Retry 与 Compensation Owner。</li><li>Protocol Adapter 可以传输工作，但不能重新定义 Position Authority 或 WorkOrder Lifecycle。</li><li>恢复运行必须证明不会重复执行后果性动作。</li></ul><h2 id="发现的矛盾" tabindex="-1">发现的矛盾 <a class="header-anchor" href="#发现的矛盾" aria-label="Permalink to &quot;发现的矛盾&quot;">​</a></h2><h3 id="自治与权限" tabindex="-1">自治与权限 <a class="header-anchor" href="#自治与权限" aria-label="Permalink to &quot;自治与权限&quot;">​</a></h3><p>Computer Use 与远程委派提高操作自治，但组织中的后果性动作仍然需要受限权限。把更多工具访问等同于更高权限，是概念错误。</p><p><strong>解决方向：</strong> 在 Position 和 WorkBoundaryContract 中分别记录 Operational Capability 与 Decision Authority。</p><h3 id="协议功能趋同与语义分化" tabindex="-1">协议功能趋同与语义分化 <a class="header-anchor" href="#协议功能趋同与语义分化" aria-label="Permalink to &quot;协议功能趋同与语义分化&quot;">​</a></h3><p>MCP Tasks 与 A2A Tasks 在传输层可能越来越相似，但前者通常服务于 Host 控制的能力集成，后者表示独立 Agent 协作。</p><p><strong>解决方向：</strong> 先选择工作模型，再选择协议；不能因为存在异步 Task Handle 就推断责任关系。</p><h3 id="中央控制与编排瓶颈" tabindex="-1">中央控制与编排瓶颈 <a class="header-anchor" href="#中央控制与编排瓶颈" aria-label="Permalink to &quot;中央控制与编排瓶颈&quot;">​</a></h3><p>Manager 模式提供统一政策与集成，但中央 Manager 可能变慢、上下文过重，或扭曲专家结果。Handoff 降低中央瓶颈，却可能使政策与完成责任碎片化。</p><p><strong>解决方向：</strong> 对边界清晰、需要聚合的工作保持 Manager Ownership；只有在转移范围、权限、返回条件和 Verifier 明确时才允许 Handoff。</p><h3 id="丰富上下文与最小权限" tabindex="-1">丰富上下文与最小权限 <a class="header-anchor" href="#丰富上下文与最小权限" aria-label="Permalink to &quot;丰富上下文与最小权限&quot;">​</a></h3><p>Handoff 与远程协作受益于上下文连续性，但安全执行要求尽量减少敏感、陈旧或被 Prompt Injection 污染的内容。</p><p><strong>解决方向：</strong> 默认使用受治理的 ContextPackage，而不是转发完整 Transcript。</p><h3 id="自我报告成功与独立验证" tabindex="-1">自我报告成功与独立验证 <a class="header-anchor" href="#自我报告成功与独立验证" aria-label="Permalink to &quot;自我报告成功与独立验证&quot;">​</a></h3><p>远程 Agent、专家或 Computer Use Loop 都可以报告成功，但调用方仍需证明业务状态正确、持久地发生了变化。</p><p><strong>解决方向：</strong> 完成应是两步协议：先 <code>claim</code>，再 <code>accept</code> 或 <code>reject</code>。</p><h2 id="尚未解决的问题" tabindex="-1">尚未解决的问题 <a class="header-anchor" href="#尚未解决的问题" aria-label="Permalink to &quot;尚未解决的问题&quot;">​</a></h2><ol><li>哪些所有权维度应进入 TMPA 核心对象，哪些只应作为 Runtime Projection？</li><li>一个 EvidenceEnvelope 能否覆盖 GUI 状态、MCP 工具结果、专家报告与 A2A Artifact，而不变得过度抽象？</li><li>Handoff 链不返回原 Manager 时，父 WorkOrder 应如何结束？</li><li>哪些 Validator 必须确定性执行，哪些场景可以接受人类判断作为验证？</li><li>外部 Agent 边界中的重复提交、超时、取消与补偿应如何表示？</li><li>远程 A2A Agent 内部调用 MCP 工具时，人类批准应在哪一层强制执行并保存证据？</li><li>怎样的证据保留策略能够支持审计，同时控制隐私与存储风险？</li></ol><h2 id="工程判断" tabindex="-1">工程判断 <a class="header-anchor" href="#工程判断" aria-label="Permalink to &quot;工程判断&quot;">​</a></h2><p>CodeFlowMu 下一阶段不应从大范围增加 A2A、MCP 或无限制 Computer Use 开始。</p><p>最高杠杆的工程顺序是：</p><h3 id="phase-0——语义基础" tabindex="-1">Phase 0——语义基础 <a class="header-anchor" href="#phase-0——语义基础" aria-label="Permalink to &quot;Phase 0——语义基础&quot;">​</a></h3><ol><li>增加 Typed Delegation 与 Boundary Event Model。</li><li>增加 <code>work_owner</code>、<code>control_owner</code>、<code>completion_claimant</code>、<code>completion_verifier</code> Projection。</li><li>定义 EvidenceEnvelope 与 CompletionVerifier 接口。</li><li>在适用流程中增加明确的 <code>waiting_human_authority</code>、<code>claim_submitted</code>、<code>verification_failed</code>、<code>accepted</code> 状态。</li></ol><h3 id="phase-1——受控-adapter" tabindex="-1">Phase 1——受控 Adapter <a class="header-anchor" href="#phase-1——受控-adapter" aria-label="Permalink to &quot;Phase 1——受控 Adapter&quot;">​</a></h3><ol><li>用前状态、后状态、审批和确定性验证封装一个本地 Computer Operation 案例。</li><li>封装一个有边界的 MCP Capability Call，且不转移父工作所有权。</li><li>使用同一个 WorkBoundaryContract，实现一个 Manager→Specialist Subtask 和一个显式 Handoff。</li><li>模拟一个 A2A 风格外部委派，包含远程 Task State 与本地 Acceptance Gate。</li></ol><h3 id="phase-2——比较实验" tabindex="-1">Phase 2——比较实验 <a class="header-anchor" href="#phase-2——比较实验" aria-label="Permalink to &quot;Phase 2——比较实验&quot;">​</a></h3><p>使用同一个有边界业务任务运行四条路径：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>manager subtask</span></span>
<span class="line"><span>handoff</span></span>
<span class="line"><span>MCP capability</span></span>
<span class="line"><span>A2A delegation</span></span></code></pre></div><p>比较：</p><ul><li>所有权清晰度；</li><li>转移的上下文；</li><li>Retry 行为；</li><li>Evidence 质量；</li><li>Final-state Verification；</li><li>中断后的恢复；</li><li>重复执行后果性动作的风险。</li></ul><p>只有当这些语义稳定后，CodeFlowMu 才应增加通用协议桥或完整 Digital Employee Studio。</p><h2 id="对-research-center-架构的影响" tabindex="-1">对 Research Center 架构的影响 <a class="header-anchor" href="#对-research-center-架构的影响" aria-label="Permalink to &quot;对 Research Center 架构的影响&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>本报告不修改 TMPA 正式出版物。它为以下概念的分离提供研究输入：</p><ul><li>工作分配；</li><li>消息转移；</li><li>Custody；</li><li>Authority Transfer；</li><li>Execution Control；</li><li>Evidence Custody；</li><li>Completion Claim；</li><li>Completion Acceptance。</li></ul><p>确定性重建应保存每次变化，而不是只根据消息顺序或文件移动进行推断。</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>Position 定义应声明：</p><ul><li>可以接受哪些工作；</li><li>可以调用哪些能力；</li><li>可以委派哪些工作；</li><li>哪些权限无需批准即可行使；</li><li>可以操作哪些应用和账户；</li><li>可以披露哪些上下文；</li><li>可以声明哪些完成；</li><li>可以最终批准哪些结果。</li></ul><p>这使数字员工从一个有名字的 Agent 变成可问责的组织工作者。</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu 现有 PM 模式应继续作为默认 Manager Model：PM 负责分解、集成与父任务完成。DEV、QA、OPS 默认贡献有边界工作，除非显式 Handoff 改变所有权。</p><p>Runtime 应显示：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>current work owner</span></span>
<span class="line"><span>active control owner</span></span>
<span class="line"><span>contributors</span></span>
<span class="line"><span>pending subtask owners</span></span>
<span class="line"><span>decision authority</span></span>
<span class="line"><span>release authority</span></span>
<span class="line"><span>completion claimant</span></span>
<span class="line"><span>completion verifier</span></span>
<span class="line"><span>last ownership transition</span></span></code></pre></div><p>FCoP 生命周期转换仍然是有价值的 Custody Evidence，但不能把文件移动单独视为完整所有权模型。</p><h2 id="queue-重新排序" tabindex="-1">Queue 重新排序 <a class="header-anchor" href="#queue-重新排序" aria-label="Permalink to &quot;Queue 重新排序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Queue 项</th><th style="text-align:right;">优先级</th><th>建议转换</th><th>原因</th></tr></thead><tbody><tr><td>WorkBoundaryContract 与 OwnershipLedger</td><td style="text-align:right;">P0</td><td>Candidate → Selected → Architecture Definition</td><td>GUI、MCP、A2A、Manager 与 Handoff 的共同前置条件。</td></tr><tr><td>CompletionVerifier 与 EvidenceEnvelope</td><td style="text-align:right;">P0</td><td>Candidate → Selected</td><td>三篇合格 Daily 均揭示完成或证据缺口。</td></tr><tr><td>Human Authority Lifecycle Node</td><td style="text-align:right;">P0</td><td>Candidate → Selected</td><td>后果性动作需要持久审批与恢复语义。</td></tr><tr><td>Comparative Boundary Experiment</td><td style="text-align:right;">P1</td><td>Candidate → Queue</td><td>用一个任务跨四种工作模型验证架构。</td></tr><tr><td>A2A–FCoP External Bridge</td><td style="text-align:right;">P2</td><td>Queue → Hold</td><td>应等待所有权与验收语义稳定。</td></tr><tr><td>General MCP Skills/Tasks Integration</td><td style="text-align:right;">P2</td><td>Queue → Hold</td><td>Capability Transport 不应早于 Host 侧 Work Contract。</td></tr><tr><td>Unrestricted Computer-use Runtime</td><td style="text-align:right;">P2</td><td>Queue → Hold</td><td>应先从受控本地应用与可执行 Validator 开始。</td></tr><tr><td>Full Digital Employee Studio</td><td style="text-align:right;">P3</td><td>Backlog 保持 Backlog</td><td>Registry 和 UI 扩展应晚于 Runtime 语义验证。</td></tr></tbody></table><h2 id="生命周期转换" tabindex="-1">生命周期转换 <a class="header-anchor" href="#生命周期转换" aria-label="Permalink to &quot;生命周期转换&quot;">​</a></h2><p>三篇源 Daily 笔记从 <code>published</code> 转换为 <code>synthesized</code>，并将 Weekly 003 记录为综合消费者。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Daily 003 source objects</span></span>
<span class="line"><span>published</span></span>
<span class="line"><span>→ synthesis_selected</span></span>
<span class="line"><span>→ cross_analyzed</span></span>
<span class="line"><span>→ synthesized_in: weekly-003</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Weekly 003</span></span>
<span class="line"><span>candidate</span></span>
<span class="line"><span>→ selected</span></span>
<span class="line"><span>→ cross_analysis_complete</span></span>
<span class="line"><span>→ architecture_judgment_complete</span></span>
<span class="line"><span>→ engineering_judgment_complete</span></span>
<span class="line"><span>→ publication_editing_complete</span></span>
<span class="line"><span>→ published</span></span>
<span class="line"><span>→ commit_verified</span></span></code></pre></div><p>这些转换不会重新打开或改写原 Daily 出版物，只记录 Daily Evidence 已被更高层综合流程消费。</p><h2 id="下周研究" tabindex="-1">下周研究 <a class="header-anchor" href="#下周研究" aria-label="Permalink to &quot;下周研究&quot;">​</a></h2><ol><li>起草 WorkBoundaryContract V0.1 研究 Schema，暂不冻结为 TMPA 对象。</li><li>定义最小 EvidenceEnvelope，并为 GUI、Capability Call、Specialist Result、Remote Agent Artifact 提供具体变体。</li><li>设计四路径比较实验与一个确定性 Final-state Validator。</li><li>定义 Human Approval、Timeout、Cancellation、Retry、Compensation 转换。</li><li>测试现有 FCoP Custody Event 能否在不修改协议的前提下投影 Proposed OwnershipLedger。</li></ol><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>本周三篇经过验证的 Daily 观察收敛为一个工程原则：</p><blockquote><p><strong>Agent 治理的核心不是更聪明地路由，而是在工作、控制、状态、权限、证据或完成发生移动的每个边界，保存可问责的所有权。</strong></p></blockquote><p>实践结论也很明确：CodeFlowMu 应先建立 Work Boundary Control Plane，再扩展协议覆盖与计算机操作自治。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ol><li><a href="./../../digital-employee/2026-08-02-computer-use-action-state-loop">Digital Employee Daily 003 — 计算机操作需要可观测的动作—状态循环</a></li><li><a href="./../../industry/2026-08-02-a2a-mcp-interoperability-boundaries">Industry Architecture Daily 003 — A2A 与 MCP 定义不同的互操作边界</a></li><li><a href="./../../engineering/2026-08-02-manager-handoff-ownership-models">Open-source Engineering Daily 003 — Manager 编排与 Handoff 表达不同的所有权模型</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/production-tests/production-test-v1/REPORT.md" target="_blank" rel="noreferrer">Research OS Engine Production Test V1——证据验证记录</a></li></ol>`,105))])}const m=t(o,[["render",p]]);export{y as __pageData,m as default};
